/// What a host reports about a command.
public struct AgentCommandReceipt: Hashable, Sendable, Codable {
    /// The command.
    public var commandId: String
    /// Its key.
    public var idempotencyKey: String
    /// Where it stands.
    public var disposition: AgentCommandDisposition
    /// Why it was rejected.
    public var errorCode: String?
    /// When the host said so.
    public var at: String

    public init(
        commandId: String,
        idempotencyKey: String,
        disposition: AgentCommandDisposition,
        errorCode: String? = nil,
        at: String
    ) {
        self.commandId = commandId
        self.idempotencyKey = idempotencyKey
        self.disposition = disposition
        self.errorCode = errorCode
        self.at = at
    }

    private enum CodingKeys: String, CodingKey {
        case commandId = "commandId"
        case idempotencyKey = "idempotencyKey"
        case disposition = "disposition"
        case errorCode = "errorCode"
        case at = "at"
    }

    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.commandId = try container.decode(String.self, forKey: .commandId)
        self.idempotencyKey = try container.decode(String.self, forKey: .idempotencyKey)
        self.disposition = try container.decode(AgentCommandDisposition.self, forKey: .disposition)
        self.errorCode = try? container.decodeIfPresent(String.self, forKey: .errorCode)
        self.at = try container.decode(String.self, forKey: .at)
    }

    public func encode(to encoder: any Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(commandId, forKey: .commandId)
        try container.encode(idempotencyKey, forKey: .idempotencyKey)
        try container.encode(disposition, forKey: .disposition)
        try container.encodeIfPresent(errorCode, forKey: .errorCode)
        try container.encode(at, forKey: .at)
    }
}

/// What an event says, by type.
public enum AgentEventPayload: Hashable, Sendable {
    /// A session began. The first event of every transcript.
    case sessionCreated(SessionCreated)
    /// What the next turn runs with. Only the fields that are set changed.
    case sessionConfigured(SessionConfigured)
    /// The session's state changed.
    case sessionState(SessionState)
    /// A turn began. Carries the turnId every event of the turn may name.
    case turnStarted(TurnStarted)
    /// A turn ended normally.
    case turnCompleted(TurnCompleted)
    /// A turn ended because something went wrong.
    case turnFailed(TurnFailed)
    /// A turn ended without finishing and without failing: a stop, a quit, a lost host. Any tool call still running has an unknown outcome.
    case turnInterrupted(TurnInterrupted)
    /// The transcript was rewound. A reader drops every turn and item it holds and rebuilds from the events that follow.
    case transcriptRestarted(TranscriptRestarted)
    /// A message from the reader.
    case itemUserMessage(ItemUserMessage)
    /// More of the agent's reply. Appended to the item's text.
    case itemAssistantTextDelta(ItemAssistantTextDelta)
    /// The whole of one reply. Replaces whatever the deltas built.
    case itemAssistantText(ItemAssistantText)
    /// More of the model's visible thinking. Appended to the item's text.
    case itemThinkingDelta(ItemThinkingDelta)
    /// A summary of the model's thinking. Replaces whatever the deltas built. Never raw private chain of thought.
    case itemThinking(ItemThinking)
    /// The agent called a tool. The call is running until its tool_result arrives.
    case itemToolCall(ItemToolCall)
    /// A chunk of a running call's live output.
    case itemToolOutput(ItemToolOutput)
    /// How a tool call ended.
    case itemToolResult(ItemToolResult)
    /// A file changed.
    case itemFileChange(ItemFileChange)
    /// A test run finished.
    case itemTestRun(ItemTestRun)
    /// A delegated agent's state, sent whenever it changes. The latest one wins.
    case itemSubagent(ItemSubagent)
    /// Older turns now reach the model as a summary. The transcript keeps them; only what the model is sent shrank.
    case itemCompaction(ItemCompaction)
    /// A quiet line the reader is owed: a hook stepped in, a setup step ran, the context was folded.
    case itemNotice(ItemNotice)
    /// The agent is waiting for a yes or a no.
    case approvalRequested(ApprovalRequested)
    /// An approval was answered.
    case approvalResolved(ApprovalResolved)
    /// The agent asked the reader something and is waiting.
    case questionAsked(QuestionAsked)
    /// A question was answered.
    case questionAnswered(QuestionAnswered)
    /// The whole todo list, as it now stands. Each snapshot replaces the last.
    case planUpdated(PlanUpdated)
    /// In plan mode, the agent proposes what it would do and waits for a decision before changing anything.
    case planProposed(PlanProposed)
    /// A proposed plan was approved or rejected.
    case planResolved(PlanResolved)
    /// Model usage incurred since the producer's previous usage report. Readers add them up.
    case usageUpdated(UsageUpdated)
    /// Something went wrong that the reader should see. Whether the turn goes on is said by the turn events, not here.
    case sessionError(SessionError)
    /// Code extension: a cloud run pushed a branch, and opened or reused a pull request.
    case codePullRequest(CodePullRequest)
    /// A type this build does not know, or a known one whose required fields
    /// were missing: kept whole, so nothing that arrives is lost or fatal.
    case unknown(type: String, raw: AgentJSONValue)

    /// The type on the wire.
    public var type: String {
        switch self {
        case .sessionCreated: "session.created"
        case .sessionConfigured: "session.configured"
        case .sessionState: "session.state"
        case .turnStarted: "turn.started"
        case .turnCompleted: "turn.completed"
        case .turnFailed: "turn.failed"
        case .turnInterrupted: "turn.interrupted"
        case .transcriptRestarted: "transcript.restarted"
        case .itemUserMessage: "item.user_message"
        case .itemAssistantTextDelta: "item.assistant_text.delta"
        case .itemAssistantText: "item.assistant_text"
        case .itemThinkingDelta: "item.thinking.delta"
        case .itemThinking: "item.thinking"
        case .itemToolCall: "item.tool_call"
        case .itemToolOutput: "item.tool_output"
        case .itemToolResult: "item.tool_result"
        case .itemFileChange: "item.file_change"
        case .itemTestRun: "item.test_run"
        case .itemSubagent: "item.subagent"
        case .itemCompaction: "item.compaction"
        case .itemNotice: "item.notice"
        case .approvalRequested: "approval.requested"
        case .approvalResolved: "approval.resolved"
        case .questionAsked: "question.asked"
        case .questionAnswered: "question.answered"
        case .planUpdated: "plan.updated"
        case .planProposed: "plan.proposed"
        case .planResolved: "plan.resolved"
        case .usageUpdated: "usage.updated"
        case .sessionError: "session.error"
        case .codePullRequest: "code.pull_request"
        case .unknown(let type, _): type
        }
    }

