        /// Where it runs.
        public var target: AgentSessionTarget
        /// The folder's display name. Never an absolute path.
        public var workspaceName: String?
        /// The repository, for a cloud session.
        public var repository: AgentRepositoryRef?
        /// The model it starts with.
        public var model: String?
        /// The thinking level it starts with.
        public var effort: AgentReasoningEffort?
        /// The permission mode it starts with.
        public var mode: AgentPermissionMode?
        /// Its title, when it has one.
        public var title: String?

        public init(
            target: AgentSessionTarget,
            workspaceName: String? = nil,
            repository: AgentRepositoryRef? = nil,
            model: String? = nil,
            effort: AgentReasoningEffort? = nil,
            mode: AgentPermissionMode? = nil,
            title: String? = nil
        ) {
            self.target = target
            self.workspaceName = workspaceName
            self.repository = repository
            self.model = model
            self.effort = effort
            self.mode = mode
            self.title = title
        }

        private enum CodingKeys: String, CodingKey {
            case target = "target"
            case workspaceName = "workspaceName"
            case repository = "repository"
            case model = "model"
            case effort = "effort"
            case mode = "mode"
            case title = "title"
        }

        public init(from decoder: any Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            self.target = try container.decode(AgentSessionTarget.self, forKey: .target)
            self.workspaceName = try? container.decodeIfPresent(String.self, forKey: .workspaceName)
            self.repository = try? container.decodeIfPresent(AgentRepositoryRef.self, forKey: .repository)
            self.model = try? container.decodeIfPresent(String.self, forKey: .model)
            self.effort = try? container.decodeIfPresent(AgentReasoningEffort.self, forKey: .effort)
            self.mode = try? container.decodeIfPresent(AgentPermissionMode.self, forKey: .mode)
            self.title = try? container.decodeIfPresent(String.self, forKey: .title)
        }

        public func encode(to encoder: any Encoder) throws {
            var container = encoder.container(keyedBy: CodingKeys.self)
            try container.encode(target, forKey: .target)
            try container.encodeIfPresent(workspaceName, forKey: .workspaceName)
            try container.encodeIfPresent(repository, forKey: .repository)
            try container.encodeIfPresent(model, forKey: .model)
            try container.encodeIfPresent(effort, forKey: .effort)
            try container.encodeIfPresent(mode, forKey: .mode)
            try container.encodeIfPresent(title, forKey: .title)
