        ) {
            self.planId = planId
            self.decision = decision
        }

        private enum CodingKeys: String, CodingKey {
            case planId = "planId"
            case decision = "decision"
        }

        public init(from decoder: any Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            self.planId = try container.decode(String.self, forKey: .planId)
            self.decision = try container.decode(AgentPlanDecision.self, forKey: .decision)
        }

        public func encode(to encoder: any Encoder) throws {
            var container = encoder.container(keyedBy: CodingKeys.self)
            try container.encode(planId, forKey: .planId)
            try container.encode(decision, forKey: .decision)
        }
    }

    /// Change what the next turn runs with. The host caps a remote sender at its own ceiling.
    public struct SessionSetMode: Hashable, Sendable, Codable {
        /// The permission mode.
        public var mode: AgentPermissionMode?
        /// The model.
        public var model: String?
        /// The thinking level.
        public var effort: AgentReasoningEffort?

        public init(
            mode: AgentPermissionMode? = nil,
            model: String? = nil,
            effort: AgentReasoningEffort? = nil
        ) {
            self.mode = mode
            self.model = model
            self.effort = effort
        }

        private enum CodingKeys: String, CodingKey {
            case mode = "mode"
            case model = "model"
            case effort = "effort"
        }

        public init(from decoder: any Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            self.mode = try? container.decodeIfPresent(AgentPermissionMode.self, forKey: .mode)
            self.model = try? container.decodeIfPresent(String.self, forKey: .model)
            self.effort = try? container.decodeIfPresent(AgentReasoningEffort.self, forKey: .effort)
        }

        public func encode(to encoder: any Encoder) throws {
            var container = encoder.container(keyedBy: CodingKeys.self)
            try container.encodeIfPresent(mode, forKey: .mode)
            try container.encodeIfPresent(model, forKey: .model)
            try container.encodeIfPresent(effort, forKey: .effort)
        }
    }

}

/// Every command carries these keys, beside its own. A command may be delivered more than once; the host acts on an idempotencyKey once.
public struct AgentCommand: Hashable, Sendable, Codable, Identifiable {
    /// The protocol version the sender wrote.
    public var v: String
    /// Unique per command.
    public var id: String
    /// Stable across retries of the same intent.
    public var idempotencyKey: String
    /// The session it is for.
    public var sessionId: String
    /// When the sender issued it.
    public var issuedAt: String
    /// After this the host must not act on it, and reports it expired.
    public var expiresAt: String?
    /// The type and its fields.
    public var payload: AgentCommandPayload

    /// The type on the wire.
    public var type: String { payload.type }

    /// Whether this build knows the type.
    public var isKnown: Bool {
        if case .unknown = payload { return false }
        return true
    }

    public init(
        v: String = JunoAgentProtocol.version,
        id: String,
        idempotencyKey: String,
        sessionId: String,
        issuedAt: String,
        expiresAt: String? = nil,
        payload: AgentCommandPayload
    ) {
        self.v = v
        self.id = id
        self.idempotencyKey = idempotencyKey
        self.sessionId = sessionId
        self.issuedAt = issuedAt
        self.expiresAt = expiresAt
        self.payload = payload
    }

    private enum EnvelopeKeys: String, CodingKey {
        case v = "v"
        case id = "id"
        case idempotencyKey = "idempotencyKey"
        case sessionId = "sessionId"
        case issuedAt = "issuedAt"
        case expiresAt = "expiresAt"
        case type = "type"
    }

    /// Tolerant in exactly the ways the TypeScript reader is: see the header of
    /// this file. Throws only when the object is not an envelope at all, or
    /// names a major version this build does not speak.
    public init(from decoder: any Decoder) throws {
        let raw = try AgentJSONValue(from: decoder)
        let container = try decoder.container(keyedBy: EnvelopeKeys.self)
        self.v = try container.decode(String.self, forKey: .v)
        guard JunoAgentProtocol.major(of: v) == JunoAgentProtocol.major else {
            throw DecodingError.dataCorruptedError(
                forKey: .v, in: container,
                debugDescription: "Agent protocol \(v) is not major \(JunoAgentProtocol.major)"
            )
        }
        self.id = try container.decode(String.self, forKey: .id)
        self.idempotencyKey = try container.decode(String.self, forKey: .idempotencyKey)
        self.sessionId = try container.decode(String.self, forKey: .sessionId)
        self.issuedAt = try container.decode(String.self, forKey: .issuedAt)
        self.expiresAt = try? container.decodeIfPresent(String.self, forKey: .expiresAt)
        let type = try container.decode(String.self, forKey: .type)
        self.payload = AgentCommandPayload(type: type, decoder: decoder) ?? .unknown(type: type, raw: raw)
    }

    public func encode(to encoder: any Encoder) throws {
        if case .unknown(_, let raw) = payload {
            try raw.encode(to: encoder)
            return
        }
        var container = encoder.container(keyedBy: EnvelopeKeys.self)
        try container.encode(v, forKey: .v)
        try container.encode(id, forKey: .id)
        try container.encode(idempotencyKey, forKey: .idempotencyKey)
        try container.encode(sessionId, forKey: .sessionId)
        try container.encode(issuedAt, forKey: .issuedAt)
        try container.encodeIfPresent(expiresAt, forKey: .expiresAt)
        try container.encode(type, forKey: .type)
        try payload.encodeFields(to: encoder)
    }
}
